import { randomBytes } from "node:crypto";
import { vi } from "vitest";

// The real @prisma/client is only generated by `prisma generate` against a
// configured database. Unit tests never touch a real database, so every
// test run substitutes a lightweight mock exposing the same enums and
// error class this codebase actually uses (see test/mocks/prisma-client.ts).
vi.mock("@prisma/client", async () => import("./mocks/prisma-client"));

// Deterministic-enough test environment. Every Gennet HTTP call in this
// suite is mocked (see test/mocks/gennet.ts and per-test fetch mocks) — no
// test in this project may reach the real Gennet API.
process.env.APP_ENCRYPTION_KEY = randomBytes(32).toString("hex");
process.env.SHOPIFY_API_KEY = "test_api_key";
process.env.SHOPIFY_API_SECRET = "test_api_secret";
process.env.SHOPIFY_APP_URL = "https://example.com";
process.env.SCOPES = "read_orders";
process.env.DATABASE_URL = "postgresql://test:test@localhost:5432/test";
